                int md = st + (en - st) / 2;
                int val = obj.query(i, md); 
                if(val == k)
                {
                    first = md; 
                    en = md-1; 
                }
                else if(val > k)
                    st = md+1; 
                else 
                    en = md-1; 
            }
            st = i;
