class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        cnt = 0
        mp = {}
        for i in range(n):
            cur_mp = {}
            if nums[i] == k:
                cnt += 1
            cur_mp[nums[i]] = 1

            for key in mp:
                res = key & nums[i]
                if res == k:
