class SGTree{
   vector<int> sg;
   public:
    SGTree(int n){
     sg.resize(4*n+1);
   }

   void build(int ind ,int low ,int high,vector<int>& arr){
      if(low==high){
          sg[ind] = arr[low];
          return ;
      }

      int mid = (low+high) >> 1;
      build(2*ind+1,low,mid,arr);
      build(2*ind+2,mid+1,high,arr);
      sg[ind] = sg[2*ind+1]&sg[2*ind+2];
   }
   //get minimum element in a range
   int query(int ind ,int low,int high,int l,int r){
      //non overlap 
      // l r low high  or low high l r
      if(r < low or l > high) return INT_MAX;
      // complete overlap
      // l low high r
      if(low >= l and high <=r) return sg[ind];

      int mid = (high+low) >> 1;
      int left = query(2*ind+1,low,mid,l,r);
      int right = query(2*ind+2,mid+1,high,l,r);
      return left&right;
   }
};

class Solution {
public:
    long long countSubarrays(vector<int>& arr, int k) {
        int n = arr.size();
        SGTree t1 = SGTree(n);
         t1.build(0 ,0 ,n-1,arr);
         long long ans = 0;
        for(int i=0;i<n;i++){
            int low = i;
            int high = n-1;
            int ind1 = -1;
            while(low<=high){
                int mid = (low+high)>>1;
                int a = t1.query(0,0,n-1,i,mid);
                if(a<=k-1){
                    high=mid-1;
                    ind1 = mid;
                }
                else{
                    low = mid+1;
                }
            }
            ind1=low;
             low = i;
             high = n-1;
            int ind2 = -1;
            while(low<=high){
                int mid = (low+high)>>1;
                int a = t1.query(0,0,n-1,i,mid);
                if(a<=k){
                    high=mid-1;
                    ind2 = mid;
                }
                else{
                    low = mid+1;
                }
            }
            ind2 = low;
            ans+=((long long)ind1-(long long)ind2);
        }
        return ans;
    }
};
